  $('constraints').innerHTML=`<table><thead><tr><th>Boundary</th><th>Original inequality</th><th>After eliminating ${r.dependent}</th><th>Touches region</th></tr></thead><tbody>${r.constraints.map(q=>`<tr><td><i class="boundary-color" style="background:${color(q)}"></i>${sub(q.label)}</td><td class="numeric">${potentialHTML(equation(q.counts))} ≤ ${fmt(q.enthalpy,4)}</td><td class="numeric">${esc(reduced(q))}</td><td>${r.vertices.some(p=>r.active(p).includes(q))?'Yes':'No'}</td></tr>`).join('')}</tbody></table>`;
  $('point-x-notation').innerHTML=potentialHTML(`Δμ${r.x} (eV/atom)`);$('point-y-notation').innerHTML=potentialHTML(`Δμ${r.y} (eV/atom)${r.system==='binary'?' · calculated':''}`);$('point-y').readOnly=r.system==='binary';$('center-point').textContent=r.system==='binary'?'Midpoint':'Interior point';
