  const co=selected?r.active(selected).map(q=>q.label):[];$('coexistence').innerHTML=selected?(co.length?`Active boundaries: ${co.map(sub).join(' · ')}`:'Interior condition: no competing-phase boundary is active.'):'No valid condition available.';
  $('vertices').innerHTML=r.vertices.length?`<table><thead><tr><th>Point</th>${r.elements.map(e=>`<th>${potentialHTML(`Δμ${e}`)} (eV/atom)</th>`).join('')}<th>Active boundaries</th></tr></thead><tbody>${r.vertices.map((p,i)=>{const m=r.chemicalPotentials(p);return `<tr><td><button class="vertex-button ${selectionName===`V${i+1}`?'selected':''}" data-vertex="${i}">V${i+1}</button></td>${r.elements.map(e=>`<td class="numeric">${fmt(m[e],6)}</td>`).join('')}<td>${r.active(p).map(q=>sub(q.label)).join(' · ')}</td></tr>`;}).join('')}</tbody></table>`:'<p class="hint">No feasible vertices for this phase set.</p>';
