  let xmin,xmax,ymin,ymax;if(r.vertices.length){xmin=Math.min(...r.vertices.map(p=>p[0]));xmax=Math.max(...r.vertices.map(p=>p[0]));ymin=Math.min(...r.vertices.map(p=>p[1]));ymax=Math.max(...r.vertices.map(p=>p[1]));}else{xmin=Math.min(-1,r.h/r.composition[r.x]);xmax=0;ymin=Math.min(-1,r.h/r.composition[r.y]);ymax=0;}
  const layout=layout2D([[xmin,xmax],[ymin,ymax]],W-L-R,H-T-B,camera);[[xmin,xmax],[ymin,ymax]]=layout.ranges;showTickInfo(layout.step);
  const sx=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),sy=y=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);plotMap={W,H,L,R,T,B,xmin,xmax,ymin,ymax,sx,sy};
  let svg=`<svg id="diagram" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Chemical-potential stability diagram for ${esc(model.target.formula)}. Use the vertex table or numeric point fields for keyboard selection."><title>${esc(model.target.formula)} chemical-potential stability</title><desc>${own?'User-supplied':'Illustrative'} energies. ${r.vertices.length} feasible vertices. Δμ in eV per atom.</desc><rect width="${W}" height="${H}" fill="white"/><defs><clipPath id="plot-clip"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>`;
  for(const x of ticks([xmin,xmax],layout.step))svg+=`<path d="M${sx(x)} ${T}V${H-B}" stroke="#e7eef2" fill="none"/><text data-axis-tick="x" x="${sx(x)}" y="${H-B+24}" text-anchor="middle" fill="#607987" font-family="monospace" font-size="13">${tickLabel(x,layout.step)}</text>`;
  for(const y of ticks([ymin,ymax],layout.step))svg+=`<path d="M${L} ${sy(y)}H${W-R}" stroke="#e7eef2" fill="none"/><text data-axis-tick="y" x="${L-13}" y="${sy(y)+4}" text-anchor="end" fill="#607987" font-family="monospace" font-size="13">${tickLabel(y,layout.step)}</text>`;
  svg+=`<path d="M${L} ${T}V${H-B}H${W-R}" stroke="#9bb0bb" fill="none"/><g clip-path="url(#plot-clip)">`;
  for(const q of r.constraints){const pts=[];if(Math.abs(q.B)>1e-12)for(const x of [xmin,xmax]){const y=(q.C-q.A*x)/q.B;if(y>=ymin-1e-8&&y<=ymax+1e-8)pts.push([x,y]);}if(Math.abs(q.A)>1e-12)for(const y of [ymin,ymax]){const x=(q.C-q.B*y)/q.A;if(x>=xmin-1e-8&&x<=xmax+1e-8)pts.push([x,y]);}if(pts.length>=2)svg+=`<line x1="${sx(pts[0][0])}" y1="${sy(pts[0][1])}" x2="${sx(pts.at(-1)[0])}" y2="${sy(pts.at(-1)[1])}" stroke="${color(q)}" stroke-width="1.3" stroke-dasharray="6 5" opacity=".55"/>`;}
  if(r.vertices.length>=3)svg+=`<polygon points="${r.vertices.map(p=>`${sx(p[0])},${sy(p[1])}`).join(' ')}" fill="#b9e9dd" fill-opacity="${camera.opacity}" stroke="#087f78" stroke-width="2.2"/>`;
