  r.vertices.forEach((p,i)=>{svg+=`<g data-vertex="${i}" style="cursor:pointer"><circle cx="${sx(p[0])}" cy="${sy(p[1])}" r="13" fill="transparent"/><circle cx="${sx(p[0])}" cy="${sy(p[1])}" r="4.5" fill="white" stroke="#087f78" stroke-width="2"/><text data-plot-label="vertex" x="${sx(p[0])+8}" y="${sy(p[1])-10}" fill="#193f4b" font-size="12" font-weight="600" font-family="system-ui" stroke="white" stroke-width="3" paint-order="stroke">V${i+1}</text></g>`;});
  if(selected&&camera.showSelectedPoint!==false)svg+=`<g pointer-events="none"><path d="M${sx(selected[0])-12} ${sy(selected[1])}h24 M${sx(selected[0])} ${sy(selected[1])-12}v24" stroke="#c25b26"/><circle cx="${sx(selected[0])}" cy="${sy(selected[1])}" r="5" fill="#c25b26" stroke="white" stroke-width="2"/></g>`;
  if(!r.vertices.length)svg+=`<text x="${W/2}" y="${H/2}" text-anchor="middle" fill="#a45a27" font-size="21" font-family="system-ui">No feasible stability region</text>`;
  svg+=`<text data-plot-label="axis" x="${(L+W-R)/2}" y="${H-15}" text-anchor="middle" font-family="system-ui" font-size="16" fill="#334e5c">${potentialSVG(`Δμ${r.x}`)} (eV / atom)</text><text data-plot-label="axis" transform="translate(21 ${(T+H-B)/2}) rotate(-90)" text-anchor="middle" font-family="system-ui" font-size="16" fill="#334e5c">${potentialSVG(`Δμ${r.y}`)} (eV / atom)</text><text x="${W-R}" y="17" text-anchor="end" fill="#7a8e98" font-family="system-ui" font-size="12">${own?'USER-SUPPLIED ENERGIES':'ILLUSTRATIVE ENERGIES'}</text></svg>`;$('plot').innerHTML=svg;applyPlotLabels();
